// Hand-written. The modules below are generated by `make types`; this file
// that declares and re-exports them is not, so a type leaving the Go source
// leaves a re-export here that only the compiler will notice.

//! QNTX Type Definitions
//!
//! This module contains Rust type definitions generated from QNTX's Go source code.
//! All types include serde Serialize/Deserialize traits for JSON compatibility.
//!
//! ## Usage
//!
//! ```rust,ignore
//! use qntx::types::{Job, JobStatus, sym};
//! ```

// Re-export all generated modules
// Note: 'async' is a reserved keyword in Rust, so we use 'async_types'
#[path = "async.rs"]
pub mod async_types;
pub mod budget;
pub mod schedule;
pub mod sym;
pub mod syscap;
// ats/types is not declared here. Rust reaches the attestation model through
// the `ats` crate, which owns it; the generated types.rs said the same thing a
// second time and nothing read it. It stops being generated when ats/types
// leaves typegen's package lists.

// Re-export commonly used types for convenience
pub use async_types::{ErrorCode, ErrorContext, Job, JobStatus, Progress, PulseState};
pub use budget::{Limiter, Tracker};
pub use syscap::Message as SystemCapabilitiesMessage;
